      "url": "https://perthpipepower.com.au/contact.html",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Do I need photos or an equipment model to send the form?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Start with the property address and a short description. Safely readable product details can help later. Photos are optional and may be emailed; do not dismantle equipment or approach water, wiring or wastewater to take them."
          }
        },
        {
          "@type": "Question",
          "name": "Does sending this form confirm the appointment or price?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. The team contacts you to agree the visit and assessment requirements. The written quote confirms the agreed work and price; submitting the form does not approve a repair or guarantee an arrival time."
          }
        },
        {
          "@type": "Question",
          "name": "Should I enter your Perth office address in the repair form?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Enter the address of the property needing work, not our office address, unless the work is at that office. Our actual Perth office is at 140 St Georges Terrace, Perth WA 6000. Contact the team before visiting to confirm arrangements."
          }
        },
        {
          "@type": "Question",
          "name": "What are your routine hours and emergency arrangements?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Routine service hours: 09:00–21:00, seven days a week. 24-hour emergency repairs are available; call to confirm attendance arrangements and the quoted emergency work. No arrival time is guaranteed. Emergency repair fees follow the quoted work plan. For urgent work, call rather than relying on an online enquiry."
          }
        }
      ]
    }
  ]
}

